import subprocess
inp=open('/tmp/inp.txt').read().strip()
p=215
def rc(s): return ''.join({'a':'t','t':'a','c':'g','g':'c'}[b] for b in reversed(s))
def tm(seq):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],capture_output=True,text=True)
    return float(r.stdout.strip())
# forward candidates: F = inp[p:p+Lf]
fwd=[]
for L in range(15,37):
    f=inp[p:p+L]
    t=tm(f)
    if 58<=t<=72: fwd.append((L,f,round(t,2)))
print("FWD candidates (Lf, seq, Tm):")
for x in fwd: print(x)
# reverse candidates: q from p+20 to p+160, Lr 15..36
rev=[]
for q in range(p+20, p+160):
    for L in range(15,37):
        r=rc(inp[q:q+L])
        t=tm(r)
        if 58<=t<=72: rev.append((q,L,r,round(t,2)))
print("\nREV candidates count:",len(rev))
# find pairs with dTm<=5, and prefer short product 60-150bp
best=[]
for (L1,f,t1) in fwd:
    for (q,L2,r,t2) in rev:
        if q < p+L1: continue
        sp=q+L2-p  # short product length approx
        if 40<=sp<=200 and abs(t1-t2)<=5:
            best.append((abs(t1-t2), t1, t2, L1, f, q, L2, r, sp))
best.sort()
print("\nbest pairs (dTm, TmF, TmR, Lf, F, q, Lr, R, shortprod):")
for b in best[:12]: print(b)
EOF
